INSERT INTO songs (song_number, title, category, songbook, song_text, tune, words, music, notes, lang, count, created_at) VALUES 
(3301, 'Лицо Твоё ярче Велик как же Ты Велик', 30, 5, 'Куплет 1\nЛицо Твоё ярче солнца, \nГлаза Твои - вселенная! \nСияем мы, как будто звезды,\nКогда смотрим на Тебя.\n\nПрипев: \nВелик, как же Ты Велик! \nВелик, как же Ты Велик!!!\n\nКуплет2: \nИ есть предел всем совершенствам, \nНо нет границ Твоим словам! \nПусть вся земля возносит песню, \nПрославляя лишь Тебя.\n\nКуплет2 Бридж: О, ооо!\nТы, подвигом любви, \nСердце из плена забрал. \nВелик, как же Ты велик, \nЧто за меня жизнь отдал!!!', '', '', '', '', 'ru', 1, NULL);